package cache

import (
	"context"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

func Connect(ctx context.Context, url string) (*redis.Client, error) {
	opts, err := redis.ParseURL(url)
	if err != nil {
		return nil, fmt.Errorf("parse REDIS_URL: %w", err)
	}
	opts.DialTimeout = time.Second
	opts.ReadTimeout = 500 * time.Millisecond
	opts.WriteTimeout = 500 * time.Millisecond

	rdb := redis.NewClient(opts)
	if err := rdb.Ping(ctx).Err(); err != nil {
		rdb.Close()
		return nil, fmt.Errorf("ping redis: %w", err)
	}
	return rdb, nil
}

package service

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/redis/go-redis/v9"

	"example.com/roombook/internal/domain"
)

const availabilityTTL = 60 * time.Second

type AvailabilityStore interface {
	Availability(ctx context.Context, roomID int64, date time.Time) (domain.Availability, error)
}

type AvailabilityService struct {
	rdb   *redis.Client
	store AvailabilityStore
	log   *slog.Logger
}

func NewAvailabilityService(rdb *redis.Client, store AvailabilityStore, log *slog.Logger) *AvailabilityService {
	return &AvailabilityService{rdb: rdb, store: store, log: log}
}

func availabilityKey(roomID int64, date time.Time) string {
	return fmt.Sprintf("roombook:availability:%d:%s", roomID, date.Format(time.DateOnly))
}

func (s *AvailabilityService) Get(ctx context.Context, roomID int64, date time.Time) (domain.Availability, error) {
	key := availabilityKey(roomID, date)
	cached, err := s.rdb.Get(ctx, key).Bytes()
	switch {
	case err == nil:
		var a domain.Availability
		if json.Unmarshal(cached, &a) == nil {
			return a, nil
		}
	case !errors.Is(err, redis.Nil):
		s.log.WarnContext(ctx, "cache read failed", "key", key, "err", err)
	}

	a, err := s.store.Availability(ctx, roomID, date)
	if err != nil {
		return domain.Availability{}, err
	}
	b, _ := json.Marshal(a)
	if err := s.rdb.Set(ctx, key, b, availabilityTTL).Err(); err != nil {
		s.log.WarnContext(ctx, "cache write failed", "key", key, "err", err)
	}
	return a, nil
}

package service

import (
	"context"
	"encoding/json"
	"math/rand/v2"
	"time"

	"github.com/redis/go-redis/v9"
	"golang.org/x/sync/singleflight"

	"example.com/roombook/internal/domain"
)

type AvailabilityService struct {
	rdb   *redis.Client
	store AvailabilityStore
	group singleflight.Group
}

func (s *AvailabilityService) Get(ctx context.Context, roomID int64, date time.Time) (domain.Availability, error) {
	key := availabilityKey(roomID, date)
	if cached, err := s.rdb.Get(ctx, key).Bytes(); err == nil {
		var a domain.Availability
		if json.Unmarshal(cached, &a) == nil {
			return a, nil
		}
	}

	v, err, _ := s.group.Do(key, func() (any, error) {
		ctx := context.WithoutCancel(ctx)
		a, err := s.store.Availability(ctx, roomID, date)
		if err != nil {
			return nil, err
		}
		b, _ := json.Marshal(a)
		ttl := availabilityTTL + time.Duration(rand.IntN(10))*time.Second
		s.rdb.Set(ctx, key, b, ttl)
		return a, nil
	})
	if err != nil {
		return domain.Availability{}, err
	}
	return v.(domain.Availability), nil
}

func (s *AvailabilityService) Invalidate(ctx context.Context, roomID int64, date time.Time) error {
	return s.rdb.Del(ctx, availabilityKey(roomID, date)).Err()
}

package service

import (
	"context"
	"log/slog"
	"time"

	"example.com/roombook/internal/domain"
)

type BookingTx interface {
	CountUpcoming(ctx context.Context, userID int64, now time.Time) (int, error)
	Insert(ctx context.Context, b domain.NewBooking) (domain.Booking, error)
}

type InTx func(ctx context.Context, fn func(BookingTx) error) error

type Cache interface {
	Invalidate(ctx context.Context, roomID int64, date time.Time) error
}

type BookingService struct {
	inTx         InTx
	availability Cache
	now          func() time.Time
	log          *slog.Logger
}

func (s *BookingService) Create(ctx context.Context, nb domain.NewBooking) (domain.Booking, error) {
	var created domain.Booking
	err := s.inTx(ctx, func(bookings BookingTx) error {
		upcoming, err := bookings.CountUpcoming(ctx, nb.UserID, s.now())
		if err != nil {
			return err
		}
		if upcoming >= 3 {
			return errBookingLimit
		}
		created, err = bookings.Insert(ctx, nb)
		return err
	})
	if err != nil {
		return domain.Booking{}, err
	}

	// Committed: the cached availability for that day is wrong now.
	if err := s.availability.Invalidate(ctx, created.RoomID, domain.LocalDate(created.StartsAt)); err != nil {
		s.log.WarnContext(ctx, "cache invalidation failed", "room", created.RoomID, "err", err)
	}
	return created, nil
}

package auth

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"time"

	"github.com/redis/go-redis/v9"
)

const sessionTTL = 7 * 24 * time.Hour

var ErrNoSession = errors.New("no such session")

type Sessions struct {
	rdb *redis.Client
}

func NewSessions(rdb *redis.Client) *Sessions { return &Sessions{rdb: rdb} }

func sessionKey(token string) string {
	sum := sha256.Sum256([]byte(token))
	return "roombook:session:" + hex.EncodeToString(sum[:])
}

func (s *Sessions) Create(ctx context.Context, userID int64) (string, error) {
	token := rand.Text()
	if err := s.rdb.Set(ctx, sessionKey(token), userID, sessionTTL).Err(); err != nil {
		return "", err
	}
	return token, nil
}

func (s *Sessions) UserID(ctx context.Context, token string) (int64, error) {
	id, err := s.rdb.GetEx(ctx, sessionKey(token), sessionTTL).Int64()
	if errors.Is(err, redis.Nil) {
		return 0, ErrNoSession
	}
	return id, err
}

func (s *Sessions) Delete(ctx context.Context, token string) error {
	return s.rdb.Del(ctx, sessionKey(token)).Err()
}

package worker

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/redis/go-redis/v9"
)

const (
	emailStream = "roombook:jobs:email"
	emailGroup  = "email"
)

type Sender interface {
	SendBookingConfirmation(ctx context.Context, bookingID int64) error
}

type EmailWorker struct {
	rdb    *redis.Client
	sender Sender
	log    *slog.Logger
}

func (w *EmailWorker) Run(ctx context.Context) error {
	err := w.rdb.XGroupCreateMkStream(ctx, emailStream, emailGroup, "0").Err()
	if err != nil && !strings.HasPrefix(err.Error(), "BUSYGROUP") {
		return err
	}
	consumer := fmt.Sprintf("worker-%d", os.Getpid())

	for ctx.Err() == nil {
		streams, err := w.rdb.XReadGroup(ctx, &redis.XReadGroupArgs{
			Group:    emailGroup,
			Consumer: consumer,
			Streams:  []string{emailStream, ">"},
			Count:    10,
			Block:    5 * time.Second,
		}).Result()
		if errors.Is(err, redis.Nil) || ctx.Err() != nil {
			continue
		}
		if err != nil {
			w.log.Error("read jobs", "err", err)
			time.Sleep(time.Second)
			continue
		}
		for _, msg := range streams[0].Messages {
			id, _ := strconv.ParseInt(fmt.Sprint(msg.Values["bookingId"]), 10, 64)
			if err := w.sender.SendBookingConfirmation(ctx, id); err != nil {
				w.log.Error("job failed, it stays pending", "id", msg.ID, "err", err)
				continue
			}
			w.rdb.XAck(ctx, emailStream, emailGroup, msg.ID)
		}
	}
	return nil
}

package api

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"time"

	"github.com/redis/go-redis/v9"
)

type roomEvent struct {
	ID   int64           `json:"id"`
	Data json.RawMessage `json:"data"`
}

func roomChannel(roomID int64) string {
	return fmt.Sprintf("roombook:rooms:%d:events", roomID)
}

func roomEvents(rdb *redis.Client) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		roomID, err := strconv.ParseInt(r.PathValue("roomID"), 10, 64)
		if err != nil {
			http.NotFound(w, r)
			return
		}
		sub := rdb.Subscribe(r.Context(), roomChannel(roomID))
		defer sub.Close()

		rc := http.NewResponseController(w)
		rc.SetWriteDeadline(time.Time{})
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		fmt.Fprint(w, "retry: 5000\n\n")
		rc.Flush()

		for {
			select {
			case <-r.Context().Done():
				return
			case msg := <-sub.Channel():
				var ev roomEvent
				if json.Unmarshal([]byte(msg.Payload), &ev) != nil {
					continue
				}
				fmt.Fprintf(w, "id: %d\nevent: availability\ndata: %s\n\n", ev.ID, ev.Data)
				if err := rc.Flush(); err != nil {
					return
				}
			}
		}
	}
}

func publishAvailability(ctx context.Context, rdb *redis.Client, roomID int64, change any) error {
	id, err := rdb.Incr(ctx, fmt.Sprintf("roombook:rooms:%d:seq", roomID)).Result()
	if err != nil {
		return err
	}
	msg, err := json.Marshal(map[string]any{"id": id, "data": change})
	if err != nil {
		return err
	}
	return rdb.Publish(ctx, roomChannel(roomID), msg).Err()
}
